  const [toolTargetNodeId,setToolTargetNodeId]=useState('');
  const [toolDialog,setToolDialog]=useState<{nodeId:string;tool:any;tools:any[]}|null>(null);
  const [publishInfo,setPublishInfo]=useState<any>(null);
  const [setupPromptCopied,setSetupPromptCopied]=useState(false);
  const [mcpDialogOpen,setMcpDialogOpen]=useState(false);
  const [theme,setTheme]=useState<'light'|'dark'>(()=>localStorage.getItem('orchestrate-theme')==='dark'?'dark':'light');
  const [auth,setAuth]=useState<User|null|undefined>(undefined); const [authMode,setAuthMode]=useState<'login'|'register'>('login'); const [authError,setAuthError]=useState(''); const [page,setPage]=useState('workflows'); const [agentView,setAgentView]=useState<'library'|'profile'>('library'); const [agentDialogOpen,setAgentDialogOpen]=useState(false); const [agentFormError,setAgentFormError]=useState(''); const [workflowView,setWorkflowView]=useState<'library'|'editor'>('library'); const [nodePickerOpen,setNodePickerOpen]=useState(false); const [nodePickerMode,setNodePickerMode]=useState<'node'|'tools'>('node'); const [nodeSearch,setNodeSearch]=useState(''); const [openCardMenu,setOpenCardMenu]=useState(''); const [graph,setGraph]=useState<G|null>(null); const [flow,setFlow]=useState<any>(null); const [savedFlowId,setSavedFlowId]=useState(''); const [flows,setFlows]=useState<SavedFlow[]>([]); const [workspace,setWorkspace]=useState<Workspace|null>(null); const [agents,setAgents]=useState<any[]>([]); const [selectedAgent,setSelectedAgent]=useState<any>(null); const [agentConnections,setAgentConnections]=useState<any[]>([]); const [agentProfilePrompt,setAgentProfilePrompt]=useState(''); const [agentProfileTemperature,setAgentProfileTemperature]=useState(0.2); const [newAgentName,setNewAgentName]=useState(''); const [newAgentProvider,setNewAgentProvider]=useState('OpenRouter'); const [newAgentModel,setNewAgentModel]=useState('openai/gpt-4o-mini'); const [newAgentCategory,setNewAgentCategory]=useState('Fast & general'); const [newAgentPrompt,setNewAgentPrompt]=useState('You are a helpful conversational AI agent. Answer clearly and concisely.'); const [saveStatus,setSaveStatus]=useState(''); const [canvasDirty,setCanvasDirty]=useState(false); const [navigationPrompt,setNavigationPrompt]=useState<(()=>void)|null>(null); const [canvasNodes,setCanvasNodes]=useState<Node[]>([]); const [selectedNodeId,setSelectedNodeId]=useState('answer'); const [activeEdge,setActiveEdge]=useState<{source:string;target:string}|null>(null); const [sessionId,setSessionId]=useState(''); const [node,setNode]=useState(''); const [message,setMessage]=useState(''); const [events,setEvents]=useState<string[]>([]); const [history,setHistory]=useState<D['history']>([]); const [busy,setBusy]=useState(false); const [error,setError]=useState('');
